def apply_random_durability_wear_on_victory(user_id, chance=None, amount=1):

    """Зберігає старий принцип: за успішного roll зношується один випадковий вдягнений предмет."""

    import random

    db = _equipment_db_9_0_12h2()

    if chance is None:

        chance = float(getattr(db, "DURABILITY_WEAR_CHANCE", 0.25))

    chance = max(0.0, min(1.0, float(chance)))

    if random.random() >= chance:

        return {"success": True, "worn": False, "damaged": 0, "items": []}

    rows = db.conn.execute(

        """

        SELECT inv.id

        FROM equipment_slots es

        JOIN inventory inv ON inv.id=es.inventory_id AND inv.user_id=es.user_id

        WHERE es.user_id=? AND es.inventory_id IS NOT NULL AND COALESCE(inv.durability,100)>0

        """,

        (int(user_id),),

    ).fetchall()

    if not rows:

        return {"success": True, "worn": False, "damaged": 0, "items": []}

    inventory_id = int(random.choice(rows)[0])

    result = reduce_equipped_item_durability(user_id, inventory_id, amount=amount)

    return {"success": bool(result.get("success")), "worn": True, "damaged": 1, "items": [result], "inventory_id": inventory_id}

def process_rng_boss_story_completion(
    *,
    user_id: int,
    mob: dict,
    location_id: str,
    encounter_id,
    registry: Mapping[str, StoryQuestDefinition] = STORY_QUEST_REGISTRY,
    connection=None,
) -> dict:
    """Record a matching ACTIVE BOSS victory without completing the quest.

    Combat reward ownership remains in the combat pipeline. This bridge only
    advances the canonical BOSS objective to its bounded target. The quest stays
    ACTIVE, reward_claimed stays unchanged, and the NPC completion owner later
    completes and rewards the quest after the player reports the victory.

    Repeated delivery of the same terminal victory is idempotent because bounded
    progress is set to the same target. Defeat and escape never call this victory
    bridge, so they leave progress unchanged and allow another invocation.
    """
    if not registry:
        return {"advanced": False, "completed": False, "reason": "no_production_content"}
    if not bool((mob or {}).get("is_boss")):
        return {"advanced": False, "completed": False, "reason": "not_boss"}
    if connection is None:
        import db
        connection = db.conn

    active = get_active_story_quest(connection, int(user_id))
    if active is None:
        return {"advanced": False, "completed": False, "reason": "no_active_quest"}

    quest = registry.get(str(active["quest_id"]))
    if quest is None:
        return {"advanced": False, "completed": False, "reason": "unknown_quest_definition"}
    if quest.quest_type is not QuestType.BOSS:
        return {"advanced": False, "completed": False, "reason": "objective_type_mismatch"}
    if quest.location_id != str(location_id):
        return {"advanced": False, "completed": False, "reason": "location_mismatch"}
    if str(quest.boss_key) != str((mob or {}).get("boss_key") or ""):
        return {"advanced": False, "completed": False, "reason": "boss_key_mismatch"}

    before = int(active["progress"])
    target = int(quest.target_quantity)
    if before >= target:
        return {
            "advanced": False,
            "completed": False,
            "reason": "already_recorded",
            "quest_id": quest.quest_id,
            "progress": before,
            "target_quantity": target,
            "encounter_id": encounter_id,
            "status": str(active["status"]),
            "reward_claimed": int(active["reward_claimed"]),
        }

    with connection:
        row = set_story_quest_progress(
            connection,
            user_id=int(user_id),
            quest_id=quest.quest_id,
            progress=target,
        )

    after = int(row["progress"])
    return {
        "advanced": after > before,
        "completed": False,
        "reason": "progress_recorded" if after > before else "already_recorded",
        "quest_id": quest.quest_id,
        "progress": after,
        "target_quantity": target,
        "encounter_id": encounter_id,
        "status": str(row["status"]),
        "reward_claimed": int(row["reward_claimed"]),
    }

def process_story_quest_item_drop(
    *,
    user_id: int,
    location_id: str,
    registry: Mapping[str, StoryQuestDefinition] = STORY_QUEST_REGISTRY,
    connection=None,
    random_value: Callable[[], float] = random.random,
) -> dict:
    """Roll and grant one dedicated quest item after terminal victory.

    Ordinary inventory, bag capacity, mob identity and ordinary loot tables are
    intentionally excluded. The lifecycle owner rechecks ACTIVE/type/location/
    item-key state and persistence bounds quantity to the definition target.
    """
    if not registry:
        return {"granted": 0, "reason": "no_production_content"}
    if connection is None:
        import db
        connection = db.conn
    active = get_active_story_quest(connection, int(user_id))
    if active is None:
        return {"granted": 0, "reason": "no_active_quest"}
    quest = registry.get(str(active["quest_id"]))
    if quest is None:
        return {"granted": 0, "reason": "unknown_quest_definition"}
    if quest.quest_type is not QuestType.QUEST_ITEM or quest.quest_item is None:
        return {"granted": 0, "reason": "objective_type_mismatch"}
    if quest.location_id != str(location_id):
        return {"granted": 0, "reason": "location_mismatch"}
    current = get_story_quest_item_quantity(
        connection, int(user_id), quest.quest_id, quest.quest_item.item_key
    )
    required = int(quest.quest_item.required_quantity)
    if current >= required:
        return {
            "granted": 0,
            "quantity": current,
            "required_quantity": required,
            "objective_complete": True,
            "reason": "target_reached",
        }
    roll = float(random_value())
    if not 0.0 <= roll < 1.0:
        raise ValueError("random_value must return a value within [0, 1)")
    if roll >= float(quest.quest_item.drop_chance):
        return {
            "granted": 0,
            "quantity": current,
            "required_quantity": required,
            "objective_complete": False,
            "reason": "drop_missed",
        }
    result = collect_active_quest_item(
        connection,
        registry=registry,
        user_id=int(user_id),
        location_id=str(location_id),
        item_key=quest.quest_item.item_key,
        amount=1,
    )
    return {
        **result,
        "item_key": quest.quest_item.item_key,
        "display_name": quest.quest_item.display_name,
        # Presentation metadata is returned only after the canonical bounded
        # grant. Consumers must display it only when granted > 0.
        "drop_message": (f"🧩 Сюжетна знахідка: {quest.quest_item.display_name}" if result.get("granted") else None),
        "reason": "granted" if result.get("granted") else "target_reached",
    }

def process_contract_progress_on_kill(user_id, mob):
    reset_daily_contracts_if_needed(user_id)

    active_contract = get_active_contract(user_id)

    if not active_contract:
        return {
            "updated": False,
            "completed": False,
            "message": None
        }

    if active_contract.get("reward_claimed"):
        return {
            "updated": False,
            "completed": False,
            "message": None
        }

    if active_contract.get("completed"):
        return {
            "updated": False,
            "completed": True,
            "message": None
        }

    mob_name = mob.get("name", "")
    mob_base_name = mob.get("base_name", mob_name)
    mob_level = int(mob.get("level", active_contract["target_mob_level"]))

    target_name = active_contract["target_mob_name"]
    target_level = int(active_contract["target_mob_level"])

    if mob_base_name != target_name or mob_level != target_level:
        return {
            "updated": False,
            "completed": False,
            "message": None
        }

    new_progress = active_contract["current_kills"] + 1

    if new_progress >= active_contract["target_kills"]:
        cursor.execute("""
        UPDATE user_active_contracts
        SET current_kills=?,
            completed=1
        WHERE id=?
        """, (
            active_contract["target_kills"],
            active_contract["id"]
        ))

        conn.commit()

        return {
            "updated": True,
            "completed": True,
            "message": (
                f"📜 Контракт виконано!\n"
                f"🎯 Ціль: {target_name}\n"
                f"✅ Прогрес: {active_contract['target_kills']}/{active_contract['target_kills']}\n"
                f"🏛️ Поверніться до Гільдії Найманців, щоб здати контракт і отримати нагороду."
            )
        }

    cursor.execute("""
    UPDATE user_active_contracts
    SET current_kills=?
    WHERE id=?
    """, (new_progress, active_contract["id"]))

    conn.commit()

    elite_note = ""

    if mob.get("is_elite"):
        elite_note = " ⭐ Елітна ціль зарахована!"

    return {
        "updated": True,
        "completed": False,
        "message": (
            f"📜 Контракт: {target_name} "
            f"{new_progress}/{active_contract['target_kills']}"
            f"{elite_note}"
        )
    }

def record_event_mob_victory(conn,event_key,user_id,mob_key,terminal_event_id,*,now=None):
    event_key=_text(event_key,"event_key"); mob_key=_text(mob_key,"mob_key"); terminal_event_id=_text(terminal_event_id,"terminal_event_id"); user_id=int(user_id)
    timestamp=(now or datetime.now(timezone.utc)).astimezone(timezone.utc).isoformat()
    conn.execute("SAVEPOINT event_kill_record")
    try:
        cur=conn.execute("INSERT OR IGNORE INTO event_kill_receipts(event_key,terminal_event_id,user_id,mob_key,recorded_at) VALUES(?,?,?,?,?)",(event_key,terminal_event_id,user_id,mob_key,timestamp))
        if cur.rowcount==0:
            conn.execute("RELEASE event_kill_record"); return {"success":True,"recorded":False,"duplicate":True}
        conn.execute("""INSERT INTO event_kill_statistics(event_key,user_id,mob_key,kills,first_reached_at,updated_at) VALUES(?,?,?,?,?,?)
          ON CONFLICT(event_key,user_id,mob_key) DO UPDATE SET kills=kills+1,updated_at=excluded.updated_at""",(event_key,user_id,mob_key,1,timestamp,timestamp))
        kills=conn.execute("SELECT kills FROM event_kill_statistics WHERE event_key=? AND user_id=? AND mob_key=?",(event_key,user_id,mob_key)).fetchone()[0]
        conn.execute("RELEASE event_kill_record"); return {"success":True,"recorded":True,"duplicate":False,"kills":int(kills)}
    except Exception:
        conn.execute("ROLLBACK TO event_kill_record"); conn.execute("RELEASE event_kill_record"); raise

